import os
import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse, parse_qs
import time
import json
from cerebras.cloud.sdk import Cerebras
import concurrent.futures
from threading import Lock
import queue
import threading
import hashlib
import re
from datetime import datetime

api_keys = ['csk-x4ypjh4j49ekvty65ncp5vnwntw8hpwj5ce9y5624y93cftf', 'csk-2e5ffjjhpv8rtvm9twh4k26kxphhkjrmcpxf6xrdcj5epfmk', 'csk-e3ht9f9w9w9nc9x8yf8ke6kr2krfkyxjj3hcvvdympd9246j', 'csk-65dkxnxnyej8rwfmpdhw46fkykvwe6j6jpk4rxxydvjxdd36']
clients = [Cerebras(api_key=key) for key in api_keys]

visited_urls = set()
content_hashes = set()
output_lock = Lock()
url_lock = Lock()
hash_lock = Lock()

output_file = "njt_legal_dataset.jsonl"
stats_file = "njt_dataset_stats.json"
stats = {"total_entries": 0, "legal_documents": 0, "total_tokens_estimate": 0, "processing_errors": 0, "unique_laws": 0}

client_queue = queue.Queue()
for client in clients:
    client_queue.put(client)

url_queue = queue.Queue()
results_queue = queue.Queue()

models = ['llama3.1-70b', 'llama3.1-8b', 'llama-3.3-70b']

base_url = ""

def get_content_hash(content):
    return hashlib.sha256(content.encode('utf-8')).hexdigest()

def is_duplicate(content):
    content_hash = get_content_hash(content)
    with hash_lock:
        if content_hash in content_hashes:
            return True
        content_hashes.add(content_hash)
        return False

def extract_legal_metadata(soup, url):
    metadata = {
        "title": "",
        "law_number": "",
        "effective_date": "",
        "ministry": "",
        "category": "",
        "status": "hatályos"
    }

    title_elem = soup.find('h1') or soup.find('h2') or soup.find('title')
    if title_elem:
        metadata["title"] = title_elem.get_text(strip=True)

        law_pattern = r'(\d+/\d+\.?\s*\([A-Z]{1,4}\.?\s*\d+\.?\))'
        match = re.search(law_pattern, metadata["title"])
        if match:
            metadata["law_number"] = match.group(1)

    for elem in soup.find_all(['div', 'span', 'p']):
        text = elem.get_text(strip=True)
        if 'hatályos' in text.lower():
            metadata["status"] = "hatályos"
        elif 'hatályon kívül' in text.lower() or 'hatálytalan' in text.lower():
            metadata["status"] = "hatálytalan"
        elif 'nem hatályos' in text.lower():
            metadata["status"] = "nem_hatályos"

        date_pattern = r'(\d{4})\.\s*(január|február|március|április|május|június|július|augusztus|szeptember|október|november|december)\s*(\d{1,2})'
        date_match = re.search(date_pattern, text)
        if date_match and not metadata["effective_date"]:
            metadata["effective_date"] = date_match.group(0)

    return metadata

def extract_legal_text(soup):
    text_content = []

    for script in soup(["script", "style", "nav", "footer", "header"]):
        script.decompose()

    main_content = soup.find('div', class_=['content', 'jogszabaly', 'main', 'document'])
    if not main_content:
        main_content = soup.find('article') or soup.find('main') or soup.body

    if main_content:
        for elem in main_content.find_all(['p', 'div', 'section', 'article', 'li']):
            text = elem.get_text(strip=True)
            if len(text) > 50:
                text_content.append(text)

    return ' '.join(text_content)

def scrape_legal_page(url):
    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        }
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()

        soup = BeautifulSoup(response.content, 'html.parser')

        metadata = extract_legal_metadata(soup, url)
        text_content = extract_legal_text(soup)

        if len(text_content) < 100:
            return None

        if is_duplicate(text_content):
            return None

        links = []
        for link in soup.find_all('a', href=True):
            href = link['href']
            full_url = urljoin(url, href)
            if 'njt.hu' in full_url and 'jogszabaly' in full_url:
                links.append(full_url)

        return {
            "url": url,
            "metadata": metadata,
            "text": text_content,
            "links": links[:20],
            "timestamp": datetime.now().isoformat()
        }

    except Exception as e:
        with output_lock:
            stats["processing_errors"] += 1
        return None

def generate_training_data(legal_data, client):
    try:
        text = legal_data["text"]
        metadata = legal_data["metadata"]

        prompt = f"""A következő magyar jogi szöveg alapján készíts részletes, strukturált training data-t.

Jogszabály címe: {metadata.get('title', 'N/A')}
Jogszabály száma: {metadata.get('law_number', 'N/A')}
Státusz: {metadata.get('status', 'N/A')}

Szöveg:
{text[:8000]}

Feladatod:
1. Fogalmazd meg a jogszabály lényegét egyszerű, világos magyar nyelven
2. Emelj ki 3-5 kulcsfontosságú jogi rendelkezést
3. Magyarázd el a jogszabály gyakorlati alkalmazását
4. Adj példákat a jogszabály hatályára
5. Kapcsold össze más releváns jogszabályokkal ha van utalás

Formátum: Strukturált, didaktikus magyarázat jogi szakzsargon kerülése mellett."""

        model = models[hash(legal_data["url"]) % len(models)]

        response = client.chat.completions.create(
            model=model,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.3,
            max_tokens=4000
        )

        generated_text = response.choices[0].message.content

        quality_score = calculate_quality_score(generated_text, metadata)

        if quality_score < 0.5:
            return None

        token_estimate = len(text.split()) + len(generated_text.split())

        return {
            "instruction": f"Magyarázd el a következő jogszabályt: {metadata.get('title', 'N/A')}",
            "input": text[:2000],
            "output": generated_text,
            "metadata": {
                "source": legal_data["url"],
                "law_number": metadata.get('law_number', ''),
                "title": metadata.get('title', ''),
                "status": metadata.get('status', ''),
                "effective_date": metadata.get('effective_date', ''),
                "quality_score": quality_score,
                "token_estimate": token_estimate,
                "model_used": model,
                "timestamp": legal_data["timestamp"]
            }
        }

    except Exception as e:
        return None

def calculate_quality_score(text, metadata):
    score = 0.5

    if len(text) > 500:
        score += 0.1
    if len(text) > 1000:
        score += 0.1

    legal_terms = ['jogszabály', 'törvény', 'rendelet', 'hatályos', 'alkalmazás', 'előírás', 'kötelezettség', 'jog', 'szabályozás', 'érvényes']
    term_count = sum(1 for term in legal_terms if term in text.lower())
    score += min(term_count * 0.03, 0.15)

    if metadata.get('law_number'):
        score += 0.1
    if metadata.get('title'):
        score += 0.05

    paragraphs = text.count('\n\n') + text.count('. ')
    if paragraphs > 3:
        score += 0.1

    return min(score, 1.0)

def save_to_jsonl(data):
    with output_lock:
        try:
            with open(output_file, 'a', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False)
                f.write('\n')

            stats["total_entries"] += 1
            stats["legal_documents"] += 1
            stats["total_tokens_estimate"] += data["metadata"]["token_estimate"]
            if data["metadata"].get("law_number"):
                stats["unique_laws"] += 1

            if stats["total_entries"] % 10 == 0:
                with open(stats_file, 'w', encoding='utf-8') as sf:
                    json.dump(stats, sf, indent=2, ensure_ascii=False)
                print(f"Feldolgozott: {stats['total_entries']} bejegyzés")

        except Exception as e:
            stats["processing_errors"] += 1

def url_worker():
    while True:
        try:
            url = url_queue.get(timeout=5)

            with url_lock:
                if url in visited_urls:
                    url_queue.task_done()
                    continue
                visited_urls.add(url)

            legal_data = scrape_legal_page(url)

            if legal_data:
                results_queue.put(legal_data)

                for link in legal_data.get("links", []):
                    with url_lock:
                        if link not in visited_urls:
                            url_queue.put(link)

            url_queue.task_done()
            time.sleep(0.5)

        except queue.Empty:
            break
        except Exception as e:
            url_queue.task_done()

def ai_worker():
    while True:
        try:
            legal_data = results_queue.get(timeout=5)

            client = client_queue.get()

            try:
                training_data = generate_training_data(legal_data, client)

                if training_data:
                    save_to_jsonl(training_data)

            finally:
                client_queue.put(client)

            results_queue.task_done()
            time.sleep(0.3)

        except queue.Empty:
            break
        except Exception as e:
            results_queue.task_done()

def discover_legal_pages():
    search_paths = [
        "/jogszabaly",
        "/",
    ]

    for path in search_paths:
        url_queue.put(urljoin(base_url, path))

    try:
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}
        response = requests.get(base_url, headers=headers, timeout=30)
        soup = BeautifulSoup(response.content, 'html.parser')

        for link in soup.find_all('a', href=True):
            href = link['href']
            full_url = urljoin(base_url, href)
            if 'njt.hu' in full_url:
                url_queue.put(full_url)

    except Exception as e:
        pass

def main():
    print("NJT.hu jogi dataset generátor indítása...")
    print(f"Kimenet: {output_file}")

    if os.path.exists(output_file):
        os.remove(output_file)
    if os.path.exists(stats_file):
        os.remove(stats_file)

    discover_legal_pages()

    url_threads = []
    for i in range(20):
        t = threading.Thread(target=url_worker, daemon=True)
        t.start()
        url_threads.append(t)

    ai_threads = []
    for i in range(30):
        t = threading.Thread(target=ai_worker, daemon=True)
        t.start()
        ai_threads.append(t)

    for t in url_threads:
        t.join()

    for t in ai_threads:
        t.join()

    with open(stats_file, 'w', encoding='utf-8') as f:
        json.dump(stats, f, indent=2, ensure_ascii=False)

    print("\n" + "="*50)
    print("Feldolgozás befejezve!")
    print(f"Összes bejegyzés: {stats['total_entries']}")
    print(f"Jogi dokumentumok: {stats['legal_documents']}")
    print(f"Egyedi jogszabályok: {stats['unique_laws']}")
    print(f"Token becslés: {stats['total_tokens_estimate']:,}")
    print(f"Hibák: {stats['processing_errors']}")
    print("="*50)

if __name__ == "__main__":
    main()
